function transform(message, context) {
  var p = message.payload || {};
  if (!p.registrationId) {
    throw new Error('registrationId is required');
  }
  context.set('registrationId', String(p.registrationId));
  context.set('transId', p.transId ? String(p.transId) : '');
  return message;
}

function transform(message, context) {
  context.set('apiUrl', context.environment === 'production'
    ? 'https://api.authorize.net/xml/v1/request.api'
    : 'https://apitest.authorize.net/xml/v1/request.api');

  var auth = {
    name: context.authNetLoginId,
    transactionKey: context.authNetTransactionKey
  };

  var transId = context.get ? context.get('transId') : context.transId;

  // All Authorize.net operations POST to the same endpoint; the root element
  // selects the operation. Field order matters (XML schema underneath).
  if (transId) {
    message.payload = {
      getTransactionDetailsRequest: {
        merchantAuthentication: auth,
        transId: transId
      }
    };
  } else {
    message.payload = {
      getUnsettledTransactionListRequest: {
        merchantAuthentication: auth,
        sorting: {
          orderBy: 'submitTimeUTC',
          orderDescending: true
        },
        paging: {
          limit: 100,
          offset: 1
        }
      }
    };
  }
  return message;
}

function transform(message, context) {
  var raw = message.payload;
  // Authorize.net prepends a UTF-8 BOM; handle string or pre-parsed object.
  if (typeof raw === 'string') {
    raw = JSON.parse(raw.replace(/^\uFEFF/, '').trim());
  }

  var registrationId = context.get ? context.get('registrationId') : context.registrationId;
  var msgs = (raw && raw.messages) ? raw.messages : {};
  if ((msgs.resultCode || '').toLowerCase() !== 'ok') {
    var m = (msgs.message && msgs.message[0]) || {};
    throw new Error('Authorize.net lookup failed: [' + m.code + '] ' + m.text);
  }

  function result(paid, t, msg) {
    return {
      paid: paid,
      transId: t ? String(t.transId) : '',
      invoiceNumber: registrationId,
      amount: t ? String(t.settleAmount != null ? t.settleAmount : t.authAmount) : '',
      status: t ? String(t.transactionStatus) : '',
      message: msg
    };
  }

  var CAPTURED = { capturedPendingSettlement: true, settledSuccessfully: true };

  if (raw.transaction) {
    // getTransactionDetails path (transId was provided).
    var t = raw.transaction;
    var order = t.order || {};
    if (String(order.invoiceNumber) !== registrationId) {
      return result(false, null, 'Transaction does not belong to this registration.');
    }
    if (String(t.responseCode) === '1' && CAPTURED[t.transactionStatus]) {
      return result(true, t, 'Payment confirmed.');
    }
    return result(false, t, 'Transaction found but not approved/captured (status: ' + t.transactionStatus + ').');
  }

  // getUnsettledTransactionList path (search by invoiceNumber).
  var list = raw.transactions || [];
  for (var i = 0; i < list.length; i++) {
    if (String(list[i].invoiceNumber) === registrationId) {
      if (CAPTURED[list[i].transactionStatus]) {
        return result(true, list[i], 'Payment confirmed.');
      }
      return result(false, list[i], 'Transaction found but not captured (status: ' + list[i].transactionStatus + ').');
    }
  }
  return result(false, null, 'No payment found yet for this registration. If you just paid, wait a moment and try again.');
}
